"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useRef, type ReactNode } from "react"

import {
  Gauge,
  GaugeArc,
  GaugeHub,
  GaugeInset,
  GaugeNeedle,
  GaugeText,
  GaugeTickLabels,
  GaugeTicks,
  GaugeTrack,
  GaugeValue,
  GaugeZones,
  type GaugeTransition,
} from "@/components/ui/gauge-kit"
import { cn } from "@/lib/utils"

import { useDriveSimulation } from "./drive-simulation"

/** Soft and without overshoot, so a dozen readings a second glide together. */
const FOLLOW: GaugeTransition = {
  type: "spring",
  visualDuration: 0.3,
  bounce: 0,
}

const MUTED = "var(--muted-foreground)"

/** Every dial fills its pod edge to edge, bar a thin margin inside the rim. */
const dial = { padding: 24, transition: FOLLOW } as const

/** Fine minor ticks, heavier majors and bold numerals inside them. */
const Scale = ({
  minor,
  major,
  labelOffset,
  labelSize,
  labelWeight,
}: {
  minor: number
  major: number
  labelOffset: number
  labelSize: number
  labelWeight: "semibold" | "bold"
}) => (
  <>
    <GaugeTicks
      count={minor}
      length={8}
      width={1.5}
      color={MUTED}
      offset={-12}
      cap="butt"
      opacity={0.6}
    />
    <GaugeTicks count={major} length={18} width={3} offset={-16} cap="butt" />
    <GaugeTickLabels
      count={major}
      offset={labelOffset}
      fontSize={labelSize}
      weight={labelWeight}
    />
  </>
)

/** A tapered pointer on a solid hub. */
const Pointer = ({ length, tail }: { length: number; tail: number }) => (
  <>
    <GaugeNeedle style="pointer" length={length} width={10} tail={tail} />
    <GaugeHub radius={12} />
  </>
)

/** The top of the scale in the foreground colour, the rest muted. */
const redline = (from: number, to: number) => [
  { to: from, color: "var(--muted)" },
  { to, color: "var(--foreground)" },
]

const Tachometer = ({ rpm }: { rpm: number }) => (
  <Gauge value={rpm} min={0} max={8} {...dial}>
    <GaugeZones zones={redline(6.5, 8)} width={10} offset={4} />
    <Scale
      minor={40}
      major={8}
      labelOffset={-52}
      labelSize={24}
      labelWeight="bold"
    />
    <Pointer length={0.88} tail={30} />
    <GaugeValue y={92} fontSize={44} font="mono" decimals={1} />
    <GaugeText y={128} fontSize={16} color={MUTED}>
      x1000 rpm
    </GaugeText>
  </Gauge>
)

/**
 * Fuel closes the speedometer's ring: same centre, same radius, filling the
 * opening left between 320 and 400 — the 40 the speed sweep started at — with
 * a few degrees clear at either end so the two arcs never touch. The sweep
 * runs clockwise, which at the foot of a dial is right to left, so the fill
 * is reversed to sit the empty end on the left and read E to F.
 */
const FuelRing = ({ fuel }: { fuel: number }) => (
  <GaugeInset
    value={fuel}
    min={0}
    max={100}
    startAngle={326}
    endAngle={394}
    transition={FOLLOW}
  >
    <GaugeTrack width={8} color="var(--muted)" opacity={1} cap="butt" />
    <GaugeArc width={8} color={MUTED} cap="butt" reverse />
    <GaugeTicks
      count={4}
      length={10}
      width={2}
      color={MUTED}
      offset={-12}
      cap="butt"
    />
    <GaugeText x={-78} y={158} fontSize={20} color={MUTED} weight="semibold">
      E
    </GaugeText>
    <GaugeText x={78} y={158} fontSize={20} color={MUTED} weight="semibold">
      F
    </GaugeText>
  </GaugeInset>
)

const Speedometer = ({ speed, fuel }: { speed: number; fuel: number }) => (
  <Gauge value={speed} min={0} max={240} {...dial}>
    <GaugeZones zones={redline(180, 240)} width={8} />
    <Scale
      minor={48}
      major={12}
      labelOffset={-54}
      labelSize={20}
      labelWeight="semibold"
    />
    <Pointer length={0.85} tail={32} />
    <GaugeValue y={56} fontSize={40} font="mono" />
    <GaugeText y={88} fontSize={16} color={MUTED}>
      km/h
    </GaugeText>
    <FuelRing fuel={fuel} />
  </Gauge>
)

/** A round instrument pod: a flat rim in the muted tone around the face. */
const Pod = ({
  className,
  children,
}: {
  className?: string
  children: ReactNode
}) => (
  <div
    className={cn(
      "aspect-square rounded-full border bg-muted p-[2.5%]",
      className
    )}
  >
    <div className="aspect-square w-full rounded-full border bg-background text-foreground [&>svg]:h-auto">
      {children}
    </div>
  </div>
)

/**
 * A twin-dial instrument cluster: the tachometer, and the speedometer with
 * fuel closing its ring. A toy drivetrain drives every reading, so the needles
 * move together the way they would on a real drive.
 */
export const CarDashboard = () => {
  const frame = useRef<HTMLDivElement>(null)
  const drive = useDriveSimulation(frame)

  return (
    <div ref={frame}>
      <div className="grid grid-cols-2 gap-4 rounded-xl border p-4 sm:gap-10 sm:px-12 sm:py-8">
        <Pod>
          <Tachometer rpm={drive.rpm} />
        </Pod>
        <Pod>
          <Speedometer speed={drive.speed} fuel={drive.fuel} />
        </Pod>
      </div>
    </div>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useId, useRef, type ReactNode } from "react"

import {
  Gauge,
  GaugeArc,
  GaugeDot,
  GaugeHub,
  GaugeInset,
  GaugeMarks,
  GaugeNeedle,
  GaugeText,
  GaugeTickLabels,
  GaugeTicks,
  GaugeTrack,
  polar,
  useAnimatedValue,
  useGauge,
  type GaugeTransition,
} from "@/components/ui/gauge-kit"

import { useFlightSimulation } from "./flight-simulation"

/** Soft and without overshoot, so a dozen readings a second glide together. */
const FOLLOW: GaugeTransition = {
  type: "spring",
  visualDuration: 0.3,
  bounce: 0,
}

const MUTED = "var(--muted-foreground)"

/** Every dial fills its pod edge to edge, bar a thin margin inside the rim. */
const dial = { padding: 24, transition: FOLLOW } as const

/** Fine minor ticks, heavier majors and numerals inside them. */
const Scale = ({
  minor,
  major,
  labels = major,
  labelSize = 30,
  format,
}: {
  minor: number
  major: number
  labels?: number
  /** Three-digit numerals need a smaller size to clear the ticks. */
  labelSize?: number
  format?: (value: number) => string
}) => (
  <>
    <GaugeTicks
      count={minor}
      length={10}
      width={1.5}
      offset={-5}
      cap="butt"
      opacity={0.5}
    />
    <GaugeTicks count={major} length={20} width={3} offset={-10} cap="butt" />
    <GaugeTickLabels
      count={labels}
      offset={-46}
      fontSize={labelSize}
      format={format}
    />
  </>
)

const Caption = ({ y, children }: { y: number; children: ReactNode }) => (
  <GaugeText y={y} fontSize={18} color={MUTED} className="tracking-widest">
    {children}
  </GaugeText>
)

/** A slim needle on a small pivot, capped in the face colour. */
const Pointer = () => (
  <>
    <GaugeNeedle style="line" length={0.88} width={5} tail={28} />
    <GaugeHub radius={14} />
    <GaugeHub radius={5} color="var(--background)" />
  </>
)

/**
 * Airspeed in knots, with the operating ranges banded under the scale: the
 * flap range inside, normal operation, the caution range, and the never
 * exceed speed as a heavy line. The gap at the top is where the sweep wraps.
 */
const AirspeedIndicator = ({ airspeed }: { airspeed: number }) => (
  <Gauge
    value={airspeed}
    min={40}
    max={200}
    startAngle={200}
    endAngle={520}
    {...dial}
  >
    <GaugeArc
      from={40}
      to={85}
      width={4}
      offset={-15}
      opacity={0.5}
      cap="butt"
    />
    <GaugeArc
      from={50}
      to={130}
      width={10}
      offset={-5}
      opacity={0.15}
      cap="butt"
    />
    <GaugeArc
      from={130}
      to={165}
      width={10}
      offset={-5}
      opacity={0.35}
      cap="butt"
    />
    <GaugeMarks values={[165]} length={24} width={4} offset={-12} cap="butt" />
    <Scale minor={32} major={8} labelSize={24} />
    <Caption y={-72}>KNOTS</Caption>
    <Pointer />
  </Gauge>
)

/** Pixels of horizon travel per degree of pitch. */
const PITCH_SCALE = 5
const HORIZON_RADIUS = 172

/**
 * The horizon behind the aircraft symbol: ground below a line, and a pitch
 * ladder every five degrees, rolled by the gauge's (animated) value and
 * shifted by the pitch. It reads the roll from the gauge so the bank pointer
 * and the horizon can never disagree.
 */
const Horizon = ({ pitch }: { pitch: number }) => {
  const { value: roll } = useGauge()
  const shown = useAnimatedValue(pitch, FOLLOW, 40)
  const clipId = `horizon${useId().replace(/\W/g, "")}`

  return (
    <g clipPath={`url(#${clipId})`}>
      <clipPath id={clipId}>
        <circle r={HORIZON_RADIUS} />
      </clipPath>
      <g transform={`rotate(${roll}) translate(0 ${shown * PITCH_SCALE})`}>
        <rect
          x={-300}
          y={0}
          width={600}
          height={400}
          fill="currentColor"
          opacity={0.1}
        />
        <line x1={-300} x2={300} stroke="currentColor" strokeWidth={2} />
        {[-20, -15, -10, -5, 5, 10, 15, 20].map((p) => {
          const half = p % 10 === 0 ? 44 : 18
          const y = -p * PITCH_SCALE
          return (
            <g key={p}>
              <line
                x1={-half}
                x2={half}
                y1={y}
                y2={y}
                stroke="currentColor"
                strokeOpacity={0.6}
                strokeWidth={2}
              />
              {p % 10 === 0 && (
                <GaugeText x={-half - 20} y={y} fontSize={16} color={MUTED}>
                  {Math.abs(p)}
                </GaugeText>
              )}
            </g>
          )
        })}
      </g>
    </g>
  )
}

/**
 * Pitch and bank. The bank scale is fixed to the case along the top; the
 * horizon and the dot riding inside the scale roll against it, and the
 * aircraft symbol stays level in front of them all.
 */
const AttitudeIndicator = ({
  bank,
  pitch,
}: {
  bank: number
  pitch: number
}) => (
  /* The value is the roll of the horizon, which turns the opposite way to
     the aircraft, and the domain puts zero straight up. */
  <Gauge
    value={-bank}
    min={-90}
    max={90}
    startAngle={90}
    endAngle={270}
    {...dial}
  >
    <Horizon pitch={pitch} />
    <GaugeMarks
      values={[-60, -30, 30, 60]}
      length={22}
      width={3}
      offset={-12}
      cap="butt"
    />
    <GaugeMarks
      values={[-45, -20, -10, 10, 20, 45]}
      length={12}
      width={2}
      offset={-17}
      cap="butt"
    />
    <GaugeMarks values={[0]} length={22} width={6} offset={-12} cap="butt" />
    <GaugeDot radius={6} offset={-38} />
    <g stroke="currentColor" strokeWidth={6} strokeLinecap="round">
      <line x1={-112} x2={-44} />
      <line x1={44} x2={112} />
    </g>
    <GaugeHub radius={7} />
  </Gauge>
)

/**
 * Two dials on one needle: thousands on the short hand and hundreds on the
 * long one, which goes round ten times for the short hand's once.
 */
const Altimeter = ({ altitude }: { altitude: number }) => (
  <Gauge
    value={altitude}
    min={0}
    max={10000}
    startAngle={180}
    endAngle={540}
    {...dial}
  >
    <Scale minor={50} major={10} format={(v) => String(v / 1000)} />
    <Caption y={-72}>ALT</Caption>
    {/* The pressure setting, in a window at three o'clock. */}
    <GaugeText x={96} fontSize={18} color={MUTED} className="tabular-nums">
      29.92
    </GaugeText>
    <GaugeNeedle style="pointer" length={0.55} width={16} tail={0} />
    <GaugeNeedle style="line" length={0.88} width={5} tail={28} turns={10} />
    <GaugeHub radius={14} />
    <GaugeHub radius={5} color="var(--background)" />
  </Gauge>
)

/** Where a wing tip sits for a turn of `rate`: level is nine o'clock. */
const LEFT_WING = { startAngle: 60, endAngle: 120 }
const RIGHT_WING = { startAngle: 240, endAngle: 300 }
/** The tail fin, straight up when the wings are level. */
const FIN = { startAngle: 150, endAngle: 210 }

const TURN = { min: -1.5, max: 1.5, transition: FOLLOW } as const

/**
 * One side of the rate scale: graduations every half rate, the sector from
 * wings level down to a standard-rate turn shaded, and heavy marks at both
 * ends of it.
 */
const TurnScale = ({ standard }: { standard: number }) => (
  <>
    <GaugeArc
      from={Math.min(0, standard)}
      to={Math.max(0, standard)}
      width={10}
      offset={-5}
      opacity={0.15}
      cap="butt"
    />
    <GaugeTicks
      count={6}
      length={10}
      width={1.5}
      offset={-5}
      cap="butt"
      opacity={0.5}
    />
    <GaugeMarks
      values={[0, standard]}
      length={22}
      width={4}
      offset={-12}
      cap="butt"
    />
  </>
)

/**
 * Rate of turn and the slip ball. The aircraft is drawn from behind: two
 * tapered wings and a fin, each a needle on its own dial sharing one value,
 * so together they bank as one symbol; the marks are wings level and a
 * standard-rate turn each way. The ball rides a glass tube at the foot.
 */
const TurnCoordinator = ({ rate, slip }: { rate: number; slip: number }) => {
  const label = (angle: number) => polar(180, angle)
  const l = label(56)
  const r = label(304)
  const wing = <GaugeNeedle style="pointer" length={0.7} width={12} tail={0} />

  return (
    <Gauge value={rate} {...TURN} {...LEFT_WING} {...dial}>
      <TurnScale standard={-1} />
      <GaugeInset value={rate} {...TURN} {...RIGHT_WING}>
        <TurnScale standard={1} />
      </GaugeInset>
      <GaugeText x={l.x} y={l.y} fontSize={22}>
        L
      </GaugeText>
      <GaugeText x={r.x} y={r.y} fontSize={22}>
        R
      </GaugeText>
      <Caption y={-112}>TURN COORDINATOR</Caption>
      <GaugeText y={-78} fontSize={16} weight="semibold">
        2 MIN
      </GaugeText>
      {/* Clockwise runs right to left along the bottom, so the ball is fed
          the slip reversed to swing the way it would. */}
      <GaugeInset
        value={-slip}
        min={-1}
        max={1}
        radius={120}
        startAngle={338}
        endAngle={382}
        transition={FOLLOW}
      >
        <GaugeTrack width={28} opacity={0.12} />
        <GaugeTrack width={1.5} offset={-14} opacity={0.4} />
        <GaugeTrack width={1.5} offset={14} opacity={0.4} />
        <GaugeMarks values={[-0.3, 0.3]} length={28} width={2} opacity={0.6} />
        <GaugeDot radius={11} />
      </GaugeInset>
      {["NO PITCH", "INFORMATION"].map((line, i) => (
        <GaugeText
          key={line}
          y={160 + i * 17}
          fontSize={13}
          color={MUTED}
          className="tracking-widest"
        >
          {line}
        </GaugeText>
      ))}
      {wing}
      <GaugeInset value={rate} {...TURN} {...RIGHT_WING}>
        {wing}
      </GaugeInset>
      <GaugeInset value={rate} {...TURN} {...FIN}>
        <GaugeNeedle style="line" length={0.17} width={6} tail={0} />
      </GaugeInset>
      <GaugeHub radius={16} />
      <GaugeHub radius={6} color="var(--background)" />
    </Gauge>
  )
}

const cardinal = ["N", "E", "S", "W"]

/**
 * The compass card turns under a fixed lubber line, so the heading is always
 * read at the top. The card is the whole gauge turned by `rotate`, which the
 * transition swings the short way round; a fixed inset over it carries the
 * lubber line and the case marks, and the autopilot's heading bug rides the
 * card.
 */
const HeadingIndicator = ({
  heading,
  target,
}: {
  heading: number
  target: number
}) => {
  const wrap = (deg: number) => ((deg % 360) + 360) % 360

  return (
    <Gauge
      value={0}
      min={0}
      max={360}
      startAngle={180}
      endAngle={540}
      rotate={-heading}
      transition={FOLLOW}
      padding={24}
    >
      <GaugeMarks
        values={[wrap(target)]}
        length={14}
        width={12}
        offset={-7}

        cap="butt"
      />
      <Scale
        minor={72}
        major={36}
        labels={12}
        format={(v) => (v % 90 === 0 ? cardinal[v / 90] : String(v / 10))}
      />
      <GaugeInset value={0} min={0} max={360} startAngle={180} endAngle={540}>
        <GaugeMarks values={[0]} length={12} width={5} offset={14} cap="butt" />
        <GaugeMarks
          values={[45, 90, 135, 225, 270, 315]}
          length={8}
          width={3}
          offset={12}
          cap="butt"
        />
      </GaugeInset>
      <Caption y={-44}>HDG</Caption>
      <GaugeText y={4} fontSize={48} weight="regular" className="tabular-nums">
        {`${String(Math.round(wrap(heading)) % 360).padStart(3, "0")}°`}
      </GaugeText>
    </Gauge>
  )
}

/**
 * Climb and descent in hundreds of feet a minute, level at nine o'clock and
 * reading up over the top for a climb and down under it for a descent. The
 * two halves meet at a single 20 at three o'clock, and level is a heavy
 * index rather than a numeral, since the needle rests on it.
 */
const VerticalSpeedIndicator = ({
  verticalSpeed,
}: {
  verticalSpeed: number
}) => (
  <Gauge
    value={verticalSpeed / 1000}
    min={-2}
    max={2}
    startAngle={-90}
    endAngle={270}
    {...dial}
  >
    <Scale
      minor={40}
      major={8}
      format={(v) => (v === 0 ? "" : String(Math.abs(v) * 10))}
    />
    <GaugeMarks values={[0]} length={34} width={5} offset={-17} cap="butt" />
    <GaugeText x={-104} y={-44} fontSize={18} color={MUTED}>
      UP
    </GaugeText>
    <GaugeText x={-104} y={44} fontSize={18} color={MUTED}>
      DN
    </GaugeText>
    <Caption y={72}>FT/MIN</Caption>
    <Pointer />
  </Gauge>
)

/** A round instrument in a flat rim, set into the panel. */
const Pod = ({ children }: { children: ReactNode }) => (
  <div className="aspect-square rounded-full border bg-muted p-[2.5%]">
    <div className="aspect-square w-full rounded-full border bg-background text-foreground [&>svg]:h-auto">
      {children}
    </div>
  </div>
)

/**
 * The six-pack of a light aircraft: airspeed, attitude and altitude across
 * the top, turn, heading and vertical speed beneath. A toy autopilot flies
 * to a new altitude or heading every so often, so every instrument moves
 * together the way it would in the air.
 */
export const Cockpit = () => {
  const frame = useRef<HTMLDivElement>(null)
  const flight = useFlightSimulation(frame)

  return (
    <div ref={frame}>
      <div className="rounded-xl border px-4 py-4 sm:px-8 sm:py-6">
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 sm:gap-6">
          <Pod>
            <AirspeedIndicator airspeed={flight.airspeed} />
          </Pod>
          <Pod>
            <AttitudeIndicator bank={flight.bank} pitch={flight.pitch} />
          </Pod>
          <Pod>
            <Altimeter altitude={flight.altitude} />
          </Pod>
          <Pod>
            <TurnCoordinator rate={flight.turnRate} slip={flight.slip} />
          </Pod>
          <Pod>
            <HeadingIndicator
              heading={flight.heading}
              target={flight.targetHeading}
            />
          </Pod>
          <Pod>
            <VerticalSpeedIndicator verticalSpeed={flight.verticalSpeed} />
          </Pod>
        </div>
      </div>
    </div>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useEffect, useRef, useState, type RefObject } from "react"

import { useInView } from "@/hooks/use-in-view"

/**
 * A toy drivetrain for the car dashboard example: it pulls away, shifts up
 * through the gears, cruises, brakes and stops again, forever. Nothing here is
 * physically accurate; it only has to move the gauges the way a real drive
 * does, with the rev needle dropping on every upshift.
 */

export type DriveReadings = {
  /** km/h */
  speed: number
  /** Thousands of rpm, which is how a tachometer is labelled. */
  rpm: number
  /** 0 for neutral, 1–6 in gear. */
  gear: number
  /** Percent of a full tank. */
  fuel: number
}

/** Where the drive is up to: what the driver is doing and until when. */
type Phase =
  | { kind: "accelerate"; target: number; throttle: number }
  | { kind: "cruise"; target: number; until: number }
  | { kind: "brake"; target: number; force: number }
  | { kind: "idle"; until: number }

type DriveState = DriveReadings & {
  throttle: number
  time: number
  phase: Phase
}

/** rpm per km/h in each gear, index 0 being neutral. */
const RATIOS = [0, 130, 76, 51, 39, 31, 25]
const IDLE = 0.8
const TOP_SPEED = 240

/** Where the drive starts, and what a reduced-motion visitor is shown. */
export const PARKED: DriveReadings = {
  speed: 0,
  rpm: IDLE,
  gear: 0,
  fuel: 64,
}

const between = (lo: number, hi: number) => lo + Math.random() * (hi - lo)
const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v))
/** Moves `from` towards `to` by at most `rate * dt`. */
const approach = (from: number, to: number, rate: number, dt: number) =>
  from + clamp(to - from, -rate * dt, rate * dt)

/** Whatever the driver does next once the current phase is over. */
const nextPhase = (s: DriveState): Phase => {
  const { speed } = s
  if (speed < 1) {
    return {
      kind: "accelerate",
      target: between(50, 130),
      throttle: between(0.5, 1),
    }
  }
  const faster = speed < 170 && Math.random() < 0.55
  if (faster) {
    return {
      kind: "accelerate",
      target: Math.min(speed + between(30, 70), 210),
      throttle: between(0.4, 1),
    }
  }
  /* Slowing down ends in a stop about a third of the time, as at lights. */
  const stop = Math.random() < 0.35
  return {
    kind: "brake",
    target: stop ? 0 : Math.max(30, speed - between(30, 70)),
    force: between(8, 18),
  }
}

const step = (s: DriveState, dt: number): DriveState => {
  const time = s.time + dt
  let { phase, speed, throttle } = s

  switch (phase.kind) {
    case "accelerate": {
      throttle = approach(throttle, phase.throttle, 2, dt)
      /* Pull tails off as the car nears its top speed. */
      speed += throttle * 13 * (1 - speed / TOP_SPEED) * dt
      if (speed >= phase.target) {
        phase = {
          kind: "cruise",
          target: phase.target,
          until: time + between(2, 5),
        }
      }
      break
    }
    case "cruise": {
      throttle = approach(throttle, 0.18 + speed / 900, 1.5, dt)
      speed = approach(speed, phase.target + Math.sin(time * 1.3) * 1.5, 3, dt)
      if (time >= phase.until) phase = nextPhase({ ...s, speed, time })
      break
    }
    case "brake": {
      throttle = approach(throttle, 0, 3, dt)
      speed = Math.max(phase.target, speed - phase.force * dt)
      if (speed <= phase.target) {
        phase =
          phase.target === 0
            ? { kind: "idle", until: time + between(1.5, 3) }
            : {
                kind: "cruise",
                target: phase.target,
                until: time + between(2, 4),
              }
      }
      break
    }
    case "idle": {
      throttle = approach(throttle, 0, 3, dt)
      if (time >= phase.until) phase = nextPhase({ ...s, speed, time })
      break
    }
  }

  /* Gears: neutral at a standstill, first to pull away, then up once the
     revs pass a point that climbs with the throttle and down when they sag. */
  let gear = s.gear
  if (speed < 2) gear = 0
  else if (gear === 0) gear = 1
  const revsIn = (g: number) => (speed * RATIOS[g]) / 1000
  const shiftUp = 2.3 + throttle * 3.8
  if (gear > 0 && gear < 6 && revsIn(gear) > shiftUp) gear += 1
  if (gear > 1 && revsIn(gear) < 1.3) gear -= 1

  /* The clutch slips below walking pace in first, so the engine holds revs. */
  const engine = gear === 0 ? IDLE + throttle * 1.2 : revsIn(gear)
  const rpm = clamp(
    Math.max(engine, IDLE + (gear === 1 ? throttle * 1.4 : 0)) +
      Math.sin(time * 9) * 0.02,
    0,
    8
  )

  /* A quick tank so the needle visibly moves, refilled when it runs low. */
  let fuel = s.fuel - (0.03 + throttle * 0.12) * dt
  if (fuel < 8) fuel = 100

  return {
    time,
    phase,
    throttle,
    speed,
    gear,
    rpm,
    fuel,
  }
}

const TICK = 1 / 12

/**
 * Runs the drive while `target` is on screen and returns the latest readings.
 * The gauges smooth between ticks with their own transition, so a dozen
 * updates a second is plenty. Visitors who prefer reduced motion get the car
 * parked with the engine running, and nothing moves.
 */
export const useDriveSimulation = (target: RefObject<Element | null>) => {
  const [readings, setReadings] = useState<DriveReadings>(PARKED)
  const state = useRef<DriveState>({
    ...PARKED,
    throttle: 0,
    time: 0,
    /* A beat of idle, then it pulls away almost as soon as it is seen. */
    phase: { kind: "idle", until: 0.3 },
  })
  const visible = useInView(target)

  useEffect(() => {
    if (!visible) return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const id = window.setInterval(() => {
      state.current = step(state.current, TICK)
      setReadings(state.current)
    }, TICK * 1000)
    return () => window.clearInterval(id)
  }, [visible])

  return readings
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useEffect, useRef, useState, type RefObject } from "react"

import { useInView } from "@/hooks/use-in-view"

/**
 * A toy light aircraft for the cockpit example: it is handed a new altitude
 * or heading every so often and flies to it, climbing, levelling off and
 * banking through turns, forever. Nothing here is aerodynamically accurate;
 * it only has to move the six instruments together the way a real flight
 * does, with the nose pitching up into a climb, the airspeed bleeding off and
 * the ball swinging out on every roll into a turn.
 */

export type FlightReadings = {
  /** Indicated airspeed, kt. */
  airspeed: number
  /** ft */
  altitude: number
  /** ft/min; positive is up. */
  verticalSpeed: number
  /** Degrees, unwrapped: it keeps counting past 360 so a dial never spins
      the long way round. */
  heading: number
  /** Degrees; positive is right wing down. */
  bank: number
  /** Degrees; positive is nose up. */
  pitch: number
  /** In standard rates (3°/s); positive is a right turn. */
  turnRate: number
  /** Ball deflection from -1 to 1; positive is out to the right. */
  slip: number
  /** Where the autopilot is taking it. */
  targetAltitude: number
  targetHeading: number
}

type FlightState = FlightReadings & { time: number; nextChange: number }

/** Where the flight starts, and what a reduced-motion visitor is shown. */
export const CRUISING: FlightReadings = {
  airspeed: 112,
  altitude: 5500,
  verticalSpeed: 0,
  heading: 270,
  bank: 0,
  pitch: 2,
  turnRate: 0,
  slip: 0,
  targetAltitude: 5500,
  targetHeading: 270,
}

const between = (lo: number, hi: number) => lo + Math.random() * (hi - lo)
const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v))
/** Moves `from` towards `to` by at most `rate * dt`. */
const approach = (from: number, to: number, rate: number, dt: number) =>
  from + clamp(to - from, -rate * dt, rate * dt)

const ALTITUDES = [3500, 4500, 5500, 6500, 7500]

/** A new clearance: another altitude, a new heading, or both. */
const nextTargets = (s: FlightState) => {
  const roll = Math.random()
  const altitude =
    roll < 0.6
      ? ALTITUDES.filter((a) => a !== s.targetAltitude)[
          Math.floor(Math.random() * (ALTITUDES.length - 1))
        ]
      : s.targetAltitude
  const heading =
    roll > 0.3
      ? s.targetHeading +
        (Math.random() < 0.5 ? -1 : 1) * Math.round(between(3, 12)) * 10
      : s.targetHeading
  return { targetAltitude: altitude, targetHeading: heading }
}

const step = (s: FlightState, dt: number): FlightState => {
  const time = s.time + dt
  let { targetAltitude, targetHeading, nextChange } = s
  if (time >= nextChange) {
    ;({ targetAltitude, targetHeading } = nextTargets(s))
    nextChange = time + between(10, 18)
  }

  /* Climb at 700 ft/min and descend at 500, easing off over the last few
     hundred feet so it levels out rather than stopping dead. */
  const altitudeError = targetAltitude - s.altitude
  const vsTarget = clamp(altitudeError * 2.5, -500, 700)
  const verticalSpeed = approach(s.verticalSpeed, vsTarget, 250, dt)
  const altitude = s.altitude + (verticalSpeed / 60) * dt

  /* Slower in the climb, faster going down, a touch slower in a turn. */
  const speedTarget =
    112 - verticalSpeed * 0.03 - Math.abs(s.bank) * 0.15 + Math.sin(time) * 0.6
  const airspeed = approach(s.airspeed, speedTarget, 2, dt)

  /* Bank towards the new heading, no steeper than 20°, and roll out as it
     comes round. */
  const headingError = targetHeading - s.heading
  const bankTarget = clamp(headingError * 1.5, -20, 20)
  const bank = approach(s.bank, bankTarget, 6, dt) + Math.sin(time * 2.3) * 0.08
  const rate = (1091 * Math.tan((bank * Math.PI) / 180)) / airspeed
  const heading = s.heading + rate * dt

  /* The nose sits higher in a climb and in a turn, with a little chop. */
  const pitch =
    2 + verticalSpeed / 140 + Math.abs(bank) * 0.08 + Math.sin(time * 1.7) * 0.3

  /* Adverse yaw swings the ball out as the wings roll, then it settles. */
  const rollRate = (bank - s.bank) / dt
  const slip = approach(
    s.slip,
    clamp(rollRate * 0.05 + Math.sin(time * 0.9) * 0.08, -1, 1),
    1.5,
    dt
  )

  return {
    time,
    nextChange,
    targetAltitude,
    targetHeading,
    airspeed,
    altitude,
    verticalSpeed,
    heading,
    bank,
    pitch,
    turnRate: rate / 3,
    slip,
  }
}

const TICK = 1 / 12

/**
 * Flies while `target` is on screen and returns the latest readings, a dozen
 * times a second; the gauges smooth between ticks. Visitors who prefer
 * reduced motion get the aircraft trimmed for cruise, and nothing moves.
 */
export const useFlightSimulation = (target: RefObject<Element | null>) => {
  const [readings, setReadings] = useState<FlightReadings>(CRUISING)
  /* The first clearance comes almost at once, so the flight is visibly
     manoeuvring as soon as it is seen. */
  const state = useRef<FlightState>({ ...CRUISING, time: 0, nextChange: 0.4 })
  const visible = useInView(target)

  useEffect(() => {
    if (!visible) return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const id = window.setInterval(() => {
      state.current = step(state.current, TICK)
      setReadings(state.current)
    }, TICK * 1000)
    return () => window.clearInterval(id)
  }, [visible])

  return readings
}

