/* ---------- charts ---------- */

/** One column per hour of the day, with a clock under every sixth. */
const Hours = ({ children }: { children: (hour: number) => ReactNode }) => (
  <div className="flex flex-col gap-1.5">
    <div className="grid h-14 grid-cols-24 gap-0.5">
