      parts={[
        { weight: wired, color: "var(--foreground)" },
        { weight: app, color: "var(--foreground)", opacity: 0.55 },
        { weight: cached, color: MUTED, opacity: 0.35 },
      ]}
    />
    <GaugeMarks
      count={4}
      length={36}
      width={6}
      cap="butt"
      color="var(--card)"
    />
    <GaugeInset value={swap} max={SWAP} transition={ARRIVE} initialValue={0}>
