      <GaugeArc width={10} offset={-40} cap="butt" color={MUTED} />
    </GaugeInset>
    <GaugeValue y={-8} fontSize={80} font="mono" decimals={1} />
    <GaugeText y={52} fontSize={24} color={MUTED}>
